datatype PState = Thinking | Hungry | Eating

datatype State = State(
  ticket: nat,
  serving: nat,
  P: seq<PState>,
  t: seq<nat>
)

predicate Init(s: State, n: nat) {
  |s.P| == n &&
  |s.t| == n &&
  s.ticket == 0 &&
  s.serving == 0 &&
  (forall i :: 0 <= i < n ==> s.P[i] == Thinking)
}

predicate Request(s: State, s': State, i: nat) {
  i < |s.P| &&
  s.P[i] == Thinking &&
  s'.ticket == s.ticket + 1 &&
  s'.serving == s.serving &&
  s'.P == s.P[i := Hungry] &&
  s'.t == s.t[i := s.ticket]
}

predicate Enter(s: State, s': State, i: nat) {
  i < |s.P| &&
  s.P[i] == Hungry &&
  s.t[i] == s.serving &&
  s'.ticket == s.ticket &&
  s'.serving == s.serving &&
  s'.P == s.P[i := Eating] &&
  s'.t == s.t
}

predicate Leave(s: State, s': State, i: nat) {
  i < |s.P| &&
  s.P[i] == Eating &&
  s'.ticket == s.ticket &&
  s'.serving == s.serving + 1 &&
  s'.P == s.P[i := Thinking] &&
  s'.t == s.t
}

predicate Next(s: State, s': State) {
  |s.P| == |s'.P| && |s.t| == |s'.t| &&
  exists i: nat :: i < |s.P| &&
    (Request(s, s', i) || Enter(s, s', i) || Leave(s, s', i))
}

// ------------------------------------------------------------------
// Correctness & Invariants
// ------------------------------------------------------------------

predicate ValidState(s: State) {
  |s.P| == |s.t|
}

// The safety property: No two distinct philosophers are eating at the same time.
predicate MutualExclusion(s: State) {
  ValidState(s) &&
  forall i, j :: 0 <= i < |s.P| && 0 <= j < |s.P| && i != j && s.P[i] == Eating ==> s.P[j] != Eating
}

// The inductive invariant that implies MutualExclusion.
predicate Inv(s: State) {
  ValidState(s) &&
  s.serving <= s.ticket &&
  // Every waiting (Hungry) or Eating philosopher holds a ticket between `serving` (inclusive) and `ticket` (exclusive).
  (forall i :: 0 <= i < |s.P| && s.P[i] != Thinking ==> s.serving <= s.t[i] < s.ticket) &&
  // An Eating philosopher's ticket matches the currently `serving` display.
  (forall i :: 0 <= i < |s.P| && s.P[i] == Eating ==> s.t[i] == s.serving) &&
  // Any two distinct philosophers who are Hungry or Eating hold distinct tickets.
  (forall i, j :: 0 <= i < |s.P| && 0 <= j < |s.P| && i != j && s.P[i] != Thinking && s.P[j] != Thinking ==> s.t[i] != s.t[j])
}

// ------------------------------------------------------------------
// Proofs
// ------------------------------------------------------------------

lemma InitImpliesInv(s: State, n: nat)
  requires Init(s, n)
  ensures Inv(s)
{}

lemma NextPreservesInv(s: State, s': State)
  requires Inv(s) && Next(s, s')
  ensures Inv(s')
{}

lemma InvImpliesMutualExclusion(s: State)
  requires Inv(s)
  ensures MutualExclusion(s)
{}

