// ------------------------------------------------------------------
// The Ticket System Specification
// ------------------------------------------------------------------
// This file formally models a concurrent system where a fixed number 
// of philosophers share a single kitchen. To ensure mutual exclusion 
// (only one philosopher in the kitchen at a time), they use a ticket 
// system with a numbered ticket dispenser and a "serving" display.
// ------------------------------------------------------------------

// A philosopher can be in one of three states:
// - Thinking: Outside the kitchen, not wanting to enter.
// - Hungry: Waiting to enter the kitchen, holding a ticket.
// - Eating: Inside the kitchen.
datatype PState = Thinking | Hungry | Eating

// The State datatype represents a snapshot of the entire concurrent system.
datatype State = State(
  ticket: nat,        // The next ticket number to be dispensed.
  serving: nat,       // The ticket number currently allowed to enter the kitchen.
  P: seq<PState>,     // The state of each philosopher (Thinking, Hungry, or Eating).
  t: seq<nat>         // The ticket number held by each philosopher.
)

// ValidState ensures that the length of the philosopher state sequence 
// matches the length of the ticket sequence. This must hold at all times.
predicate ValidState(s: State) {
  |s.P| == |s.t|
}

// ------------------------------------------------------------------
// State Transitions (The rules of the system)
// ------------------------------------------------------------------

// Init defines the starting state of the system for `n` philosophers.
predicate Init(s: State, n: nat) {
  ValidState(s) &&
  |s.P| == n &&       // The system has exactly `n` philosophers.
  s.ticket == 0 &&    // The ticket dispenser starts at 0.
  s.serving == 0 &&   // The serving display starts at 0.
  // Initially, every philosopher is outside the kitchen just thinking.
  (forall i :: 0 <= i < n ==> s.P[i] == Thinking)
}

// Request: A philosopher decides they are hungry and takes a ticket.
// This is an atomic operation.
predicate Request(s: State, s': State, i: nat) {
  ValidState(s) &&
  i < |s.P| &&
  s.P[i] == Thinking &&           // The philosopher must currently be thinking.
  s'.ticket == s.ticket + 1 &&    // The ticket dispenser increments.
  s'.serving == s.serving &&      // The serving display remains unchanged.
  s'.P == s.P[i := Hungry] &&     // The philosopher becomes Hungry.
  s'.t == s.t[i := s.ticket]      // The philosopher grabs the current ticket number.
}

// Enter: A hungry philosopher enters the kitchen when their ticket is called.
predicate Enter(s: State, s': State, i: nat) {
  ValidState(s) &&
  i < |s.P| &&
  s.P[i] == Hungry &&             // The philosopher must be waiting (Hungry).
  s.t[i] == s.serving &&          // They can ONLY enter if their ticket matches the display.
  s'.ticket == s.ticket &&        // The ticket dispenser remains unchanged.
  s'.serving == s.serving &&      // The serving display remains unchanged.
  s'.P == s.P[i := Eating] &&     // The philosopher enters the kitchen (Eating).
  s'.t == s.t                     // Tickets held by everyone remain the same.
}

// Leave: A philosopher finishes eating, leaves the kitchen, and advances the display.
predicate Leave(s: State, s': State, i: nat) {
  ValidState(s) &&
  i < |s.P| &&
  s.P[i] == Eating &&             // The philosopher must currently be inside the kitchen.
  s'.ticket == s.ticket &&        // The ticket dispenser remains unchanged.
  s'.serving == s.serving + 1 &&  // They press the button to increment the serving display.
  s'.P == s.P[i := Thinking] &&   // The philosopher goes back to Thinking.
  s'.t == s.t                     // Tickets held by everyone remain the same.
}

// Next represents any possible single atomic step the system can take.
// It non-deterministically chooses a philosopher `i` and one valid transition.
predicate Next(s: State, s': State) {
  ValidState(s) && ValidState(s') &&
  exists i: nat :: i < |s.P| &&
    (Request(s, s', i) || Enter(s, s', i) || Leave(s, s', i))
}

// ------------------------------------------------------------------
// Correctness & Invariants (Proving the system is safe)
// ------------------------------------------------------------------

// The core safety property we want to prove: Mutual Exclusion.
// It states that no two distinct philosophers (i and j) can be Eating at the same time.
predicate MutualExclusion(s: State) {
  ValidState(s) &&
  forall i, j :: 0 <= i < |s.P| && 0 <= j < |s.P| && i != j && s.P[i] == Eating ==> s.P[j] != Eating
}

// The Inductive Invariant (Inv) is a stronger property that implies MutualExclusion.
// To prove a concurrent system safe, we must provide an invariant that:
// 1. Holds in the initial state.
// 2. Is preserved by every possible transition (Next).
// 3. Logically implies the safety property (MutualExclusion).
predicate Inv(s: State) {
  ValidState(s) &&

  // 1. The serving display never exceeds the next available ticket from the dispenser.
  s.serving <= s.ticket &&

  // 2. Any philosopher actively waiting (Hungry) or Eating holds a valid ticket.
  // This ticket is between the currently serving number (inclusive) and the next dispenser number (exclusive).
  (forall i :: 0 <= i < |s.P| && s.P[i] != Thinking ==> s.serving <= s.t[i] < s.ticket) &&

  // 3. A philosopher who is inside the kitchen (Eating) MUST hold the ticket that matches the display.
  (forall i :: 0 <= i < |s.P| && s.P[i] == Eating ==> s.t[i] == s.serving) &&

  // 4. No two distinct active philosophers (Hungry or Eating) hold the same ticket number.
  // Because they all take sequential tickets from the dispenser, their tickets are strictly unique.
  (forall i, j :: 0 <= i < |s.P| && 0 <= j < |s.P| && i != j && s.P[i] != Thinking && s.P[j] != Thinking ==> s.t[i] != s.t[j])
}

// ------------------------------------------------------------------
// Proofs (Dafny verifies these lemmas automatically based on Inv)
// ------------------------------------------------------------------

// Lemma 1: The Initial state satisfies our invariant.
lemma InitImpliesInv(s: State, n: nat)
  requires Init(s, n)
  ensures Inv(s)
{}

// Lemma 2: If the system is in a state satisfying the invariant, and takes any valid step (Next),
// the resulting state s' will ALSO satisfy the invariant.
lemma NextPreservesInv(s: State, s': State)
  requires Inv(s) && Next(s, s')
  ensures Inv(s')
{}

// Lemma 3: If the invariant holds, then Mutual Exclusion holds.
// (Because if two were Eating, they would both hold the `serving` ticket, violating uniqueness).
lemma InvImpliesMutualExclusion(s: State)
  requires Inv(s)
  ensures MutualExclusion(s)
{}

