@"

// ------------------------------------------------------------------
// Liveness & Starvation Freedom (Progress)
// ------------------------------------------------------------------

// To prove starvation freedom, we must show that if a philosopher `i` 
// is Hungry, the system is not deadlocked, and some philosopher can 
// take a step that brings `i` closer to Eating.

// A philosopher is enabled to Enter if they are Hungry and their ticket is called.
predicate EnabledEnter(s: State, i: nat) {
  ValidState(s) && i < |s.P| && s.P[i] == Hungry && s.t[i] == s.serving
}

// A philosopher is enabled to Leave if they are currently Eating.
predicate EnabledLeave(s: State, i: nat) {
  ValidState(s) && i < |s.P| && s.P[i] == Eating
}

// Lemma 4: Starvation Freedom (Progress)
// If philosopher `i` is Hungry, then either:
// 1. Philosopher `i` is enabled to Enter right now.
// 2. Some other philosopher `j` holds the current turn (`serving`) and is enabled to Enter or Leave.
// Because they are enabled, they can take a step, eventually advancing `serving` and 
// bringing `i` strictly closer to Eating.
lemma StarvationFreedom_Progress(s: State, i: nat)
  requires Inv(s)
  requires i < |s.P| && s.P[i] == Hungry
  ensures EnabledEnter(s, i) || (exists j :: 0 <= j < |s.P| && j != i && (EnabledEnter(s, j) || EnabledLeave(s, j)))
{
  if s.t[i] == s.serving {
    // Philosopher i's ticket is up! They can Enter immediately.
  } else {
    // i is waiting because their ticket hasn't been called yet.
    // By Invariant #2, s.serving < s.t[i] < s.ticket.
    assert s.serving <= s.serving < s.ticket;

    // By Invariant #5 (No Missing Tickets), there MUST be SOME philosopher `j` 
    // who currently holds the `serving` ticket.
    // Since `s.t[j] == s.serving` and `s.t[i] != s.serving`, we know `j != i`.
    // Because `j` is not Thinking (they hold an active ticket), they are either Hungry or Eating.
    // If they are Hungry, `EnabledEnter` holds for them.
    // If they are Eating, `EnabledLeave` holds for them.
  }
}
